style.css:
@-moz-document domain("substack.com") {
/* List here any scope that RE-DECLARES the token scale from a source we do
     not own — an own declaration beats an inherited !important
     (`.substack-theme`/`.light-theme`: --color-light-*; `.force-light-theme`: the
     legacy --web_bg_color scale). Scopes that only rebind onto families set here,
     or fed by an input darkened below, need no entry. */
  :root,
  .substack-theme,
  .light-theme,
  .force-light-theme,
  [class*="pubTheme"],
  [class*="headerTheme"] {
    color-scheme: dark;

    /* Neutral background scale */
    --color-bg-primary: #14181d !important;
    --color-bg-primary-themed: #14181d !important;
    --color-bg-primary-hover: #1a1f26 !important;
    --color-bg-primary-hover-themed: #1a1f26 !important;
    --color-bg-secondary: #1c2128 !important;
    --color-bg-secondary-themed: #1c2128 !important;
    --color-bg-secondary-hover-themed: #262c33 !important;
    --color-bg-tertiary: #262c33 !important;
    --color-bg-tertiary-themed: #262c33 !important;
    --color-bg-quaternary: #2d333b !important;
    --color-bg-elevated-primary: #1c2128 !important;
    --color-bg-elevated-secondary: #262c33 !important;
    --color-bg-elevated-tertiary: #363b42 !important;
    --color-bg-elevated-themed: #1c2128 !important;
    --color-bg-elevated-hover-themed: #262c33 !important;
    --color-bg-sunken-primary: #0d1117 !important;
    --web_bg_color: #14181d !important;
    --background_contrast_1: #1c2128 !important;
    --background_contrast_2: #262c33 !important;
    --background_contrast_3: #363b42 !important;
    --background_contrast_4: #4a515a !important;
    --background_contrast_5: #8b949e !important;

    /* Foreground / text scale */
    --color-fg-primary: #e6edf3 !important;
    --color-fg-primary-themed: #e6edf3 !important;
    --color-fg-secondary: #c4cdd6 !important;
    --color-fg-secondary-themed: #c4cdd6 !important;
    --color-fg-tertiary: #8b949e !important;
    --color-fg-tertiary-themed: #8b949e !important;
    --print_on_web_bg_color: #e6edf3 !important;
    --print_secondary_on_web_bg_color: #8b949e !important;

    /* Semantic INK (mentions, link previews, status labels): the site's own
       dark-scheme values. Set both the alias and the --color-light-* source — some
       rules name the light token. The matching -bg-primary* fills stay untouched:
       they carry white ink and are identical in both schemes. */
    --color-semantic-highlight-fg-primary: rgb(24, 160, 251) !important;
    --color-light-semantic-highlight-fg-primary: rgb(24, 160, 251) !important;
    --color-semantic-select-fg-primary: rgb(0, 118, 255) !important;
    --color-light-semantic-select-fg-primary: rgb(0, 118, 255) !important;
    --color-semantic-error-fg-primary: rgb(255, 119, 114) !important;
    --color-light-semantic-error-fg-primary: rgb(255, 119, 114) !important;
    --color-semantic-success-fg-primary: rgb(82, 221, 152) !important;
    --color-light-semantic-success-fg-primary: rgb(82, 221, 152) !important;
    --color-semantic-warn-fg-primary: rgb(255, 223, 65) !important;
    --color-light-semantic-warn-fg-primary: rgb(255, 223, 65) !important;
    --color-semantic-paid-fg-primary: rgb(155, 125, 255) !important;
    --color-light-semantic-paid-fg-primary: rgb(155, 125, 255) !important;
    --color-semantic-substack-fg-primary: rgb(255, 133, 61) !important;
    --color-light-semantic-substack-fg-primary: rgb(255, 133, 61) !important;

    /* Borders / hairlines */
    --color-utility-detail: rgba(255, 255, 255, 0.1) !important;
    --color-utility-detail-themed: #2d333b !important;
    --border-primary-themed: 1px solid #2d333b !important;

    /* Light-scheme primitives */
    --color-light-bg-primary: #14181d !important;
    --color-light-bg-primary-hover: #1a1f26 !important;
    --color-light-bg-secondary: #1c2128 !important;
    --color-light-bg-tertiary: #262c33 !important;
    --color-light-bg-quaternary: #2d333b !important;
    --color-light-bg-elevated-primary: #1c2128 !important;
    --color-light-bg-elevated-secondary: #262c33 !important;
    --color-light-bg-elevated-tertiary: #363b42 !important;
    --color-light-bg-sunken-primary: #0d1117 !important;
    --color-light-fg-primary: #e6edf3 !important;
    --color-light-fg-secondary: #c4cdd6 !important;
    --color-light-fg-tertiary: #8b949e !important;
    --color-light-utility-detail: rgba(255, 255, 255, 0.1) !important;

    /* Publication-themed surfaces. Pop/accent members stay untouched — each
       newsletter keeps its own accent; --color_theme_print_on_pop stays white, it is
       the ink that sits on the accent. */
    --color_theme_bg_elevated: #1c2128 !important;
    --color_theme_bg_elevated_secondary: #262c33 !important;
    --color_theme_bg_elevated_tertiary: #363b42 !important;
    --color_theme_bg_contrast_1: #1c2128 !important;
    --color_theme_bg_contrast_2: #262c33 !important;
    --color_theme_bg_contrast_3: #363b42 !important;
    --color_theme_bg_contrast_4: #4a515a !important;
    --color_theme_bg_contrast_5: #8b949e !important;
    --color_theme_detail: #2d333b !important;
    --cover_bg_color: #14181d !important;
    --cover_bg_color_secondary: #1c2128 !important;
    --cover_print_primary: #e6edf3 !important;
    --cover_print_secondary: #c4cdd6 !important;
    --cover_print_tertiary: #8b949e !important;

    /* Publication header surfaces (--header_*) */
    --header_bg_color: #14181d !important;
    --header_bg_elevated: #1c2128 !important;
    --header_bg_elevated_secondary: #262c33 !important;
    --header_bg_elevated_tertiary: #363b42 !important;
    --header_bg_contrast_1: #1c2128 !important;
    --header_bg_contrast_2: #262c33 !important;
    --header_bg_contrast_3: #363b42 !important;
    --header_bg_contrast_4: #4a515a !important;
    --header_detail_color: #2d333b !important;
    --print_on_header_bg_color: #e6edf3 !important;
    --print_secondary_on_header_bg_color: #8b949e !important;

    /* Publication footer + subscribe surfaces. Their wrappers rebind the
       --color-bg-/-fg- scale onto these and do not always carry `pubTheme`, so the
       pub-configured INPUT must be dark too. */
    --footer_bg_color: #14181d !important;
    --footer_bg_elevated: #1c2128 !important;
    --footer_bg_elevated_secondary: #262c33 !important;
    --footer_bg_elevated_tertiary: #363b42 !important;
    --footer_bg_contrast_1: #1c2128 !important;
    --footer_bg_contrast_2: #262c33 !important;
    --footer_bg_contrast_3: #363b42 !important;
    --footer_detail_color: #2d333b !important;
    --print_on_footer_bg_color: #e6edf3 !important;
    --print_secondary_on_footer_bg_color: #8b949e !important;
    --footer_secondary_bg_color: #14181d !important;
    --footer_secondary_bg_elevated: #1c2128 !important;
    --footer_secondary_bg_elevated_secondary: #262c33 !important;
    --footer_secondary_bg_elevated_tertiary: #363b42 !important;
    --footer_secondary_bg_contrast_1: #1c2128 !important;
    --footer_secondary_bg_contrast_2: #262c33 !important;
    --footer_secondary_bg_contrast_3: #363b42 !important;
    --footer_secondary_detail_color: #2d333b !important;
    --print_on_footer_secondary_bg_color: #e6edf3 !important;
    --print_secondary_on_footer_secondary_bg_color: #8b949e !important;
    --subscribe_bg_color: #14181d !important;
    --subscribe_bg_elevated: #1c2128 !important;
    --subscribe_bg_elevated_secondary: #262c33 !important;
    --subscribe_bg_elevated_tertiary: #363b42 !important;
    --subscribe_bg_contrast_1: #1c2128 !important;
    --subscribe_bg_contrast_2: #262c33 !important;
    --subscribe_bg_contrast_3: #363b42 !important;
    --subscribe_detail_color: #2d333b !important;
    --print_on_subscribe_bg_color: #e6edf3 !important;
    --print_secondary_on_subscribe_bg_color: #8b949e !important;

    /* Slightly deeper scrim on dark */
    --color-utility-modal: rgba(0, 0, 0, 0.65) !important;
  }

  /* Page canvas (html bg is hardcoded white) */
  html,
  body {
    background-color: #14181d !important;
  }

  /* Reader/app shell palette: --color-app-light-* is declared on `body` and
     again in a style ATTRIBUTE per node, so a :root override reaches neither.
     Redefining the source also carries the 50+ derived tokens; accent members
     stay untouched. */
  body,
  [class*="appTheme"] {
    --color-app-light-fg-primary: #e6edf3 !important;
    --color-app-light-fg-secondary: #c4cdd6 !important;
    --color-app-light-fg-tertiary: #8b949e !important;
    --color-app-light-bg-primary: #14181d !important;
    --color-app-light-bg-primary-hover: #1a1f26 !important;
    --color-app-light-bg-secondary: #1c2128 !important;
    --color-app-light-bg-tertiary: #262c33 !important;
    --color-app-light-bg-quaternary: #2d333b !important;
  }

  /* App-shell nav logo: --color-nav-logo aliases to a SURFACE token here.
     Scope-local — :root keeps the brand orange on the hub — so never set this
     globally. */
  .pc-root.app-theme,
  [class*="appTheme"] {
    --color-nav-logo: #8b949e !important;
  }

  /* Code blocks (plain <pre>/<code>, no highlight classes) */
  pre,
  code,
  kbd,
  samp {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
  }
  pre code {
    background-color: transparent !important;
  }

  /* Inputs / textareas.
     `emailInputOnAccentBackground` keeps the site's fill, ink and placeholder (the
     accent band's own fill); subscribe email inputs keep the pub accent as their
     border, so the border override skips them too.
     Checkbox/radio: with `appearance: auto` a background-color override replaces
     the native paint, tick/dot included.
     Button-ish types are out like `<button>`: CONTROLS, not fields. */
  input:not([class*="emailInputOnAccentBackground"]):not([type="checkbox"]):not([type="radio"]):not([type="submit"]):not([type="button"]):not([type="reset"]):not([type="image"]),
  textarea,
  select {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
  }
  /* `:not(:focus)` is load-bearing: Pencraft draws the focus ring as
     `border: var(--border-focus)`, which a blanket border-color override would
     outrank. */
  input:not([class*="emailInput"]):not([class*="email-input"]):not([type="checkbox"]):not([type="radio"]):not([type="submit"]):not([type="button"]):not([type="reset"]):not([type="image"]):not(:focus),
  textarea:not(:focus),
  select:not(:focus) {
    border-color: #2d333b !important;
  }
  input:not([class*="emailInputOnAccentBackground"])::placeholder,
  textarea::placeholder {
    color: #8b949e !important;
  }

  /* Empty image placeholders */
  [class*="containerEmpty"],
  [class*="imagePlaceholder"] {
    background-color: #1c2128 !important;
  }

  /* Welcome / intro popup */
  .intro-popup {
    background-color: #1c2128 !important;
  }

  /* Discover/explore selected category tab. Scoped to priority_secondary so
     pub nav tabs are untouched. */
  [role="tab"][aria-selected="true"][class*="priority_secondary"] {
    background-color: #363b42 !important;
    color: #e6edf3 !important;
  }
  /* The fill above is `!important`, so the site's hover lift must be
     restated. */
  [role="tab"][aria-selected="true"][class*="priority_secondary"]:hover {
    background-color: #4a515a !important;
  }

  /* Archive month dividers share the `meta-` family with the byline dates, so
     they take that grey, not the accent-ink neutral below. */
  [class*="monthHeader"] {
    color: #8b949e !important;
  }

  /* Accent used as INK.
     One pub accent is both fill (--background_pop, kept — the brand) and ink
     (--print_pop / --color-accent-text). The ink may be arbitrarily dark (1.1:1
     here) and static CSS cannot lighten only the dark ones, so it goes neutral;
     the underline must then be currentColor, an accent one being invisible on
     exactly those accents. `.button`/`.image-link` are text-less, stay out.
     `[class*="color-accent-"]` lands on whatever owns the text, not always an
     anchor; the month header wears it too and keeps the grey set above. */
  .body.markup a:not(.button):not(.image-link),
  a.linkified {
    color: #e6edf3 !important;
    text-decoration-line: underline !important;
    text-decoration-color: currentColor !important;
  }
  [class*="color-accent-"]:not([class*="monthHeader"]),
  a.thread-head-cta {
    color: #e6edf3 !important;
  }
  /* The wash stays — it is the hit cue; only the ink moves. Scoped to
     `pubAccentTheme-`: outside it --color-link-fg is the semantic-highlight blue
     set above. */
  [class*="pubAccentTheme"] [class*="highlight-"] {
    color: #e6edf3 !important;
  }

  /* Tags feed the accent into the Tag component's own --color-theme-fg; the
     outline stays accent-tinted. */
  [class*="tag-"][class*="theme_accent"] {
    --color-theme-fg: #c4cdd6 !important;
  }

  /* Accent as INK on a transparent fill. Remap the token, not the hashed
     class, so a bundle rename cannot drop the hook; scope to the pub wrapper,
     since on the hub the token is the brand orange. -bg-hover untouched. */
  [class*="pubTheme"] {
    --color-button-tertiary-accent-fg: #e6edf3 !important;
    --color-button-tertiary-accent-fg-hover: #e6edf3 !important;
  }

  /* Sticky publication nav spacer (reserves header height) */
  .main-menu > div {
    background-color: #14181d !important;
  }

  /* www marketing nav "Sign in" pill */
  .homepage-nav [class*="bg-white"] {
    background-color: #262c33 !important;
  }

  /* www marketing burger: its hardcoded stroke attribute is inherited by the
     <line> children. */
  .homepage-nav .burger-icon,
  .homepage-nav .burger-icon * {
    stroke: #e6edf3 !important;
  }

  /* www marketing mobile slide-in menu */
  .homepage-nav-mobile-menu {
    background-color: #14181d !important;
  }
  /* Colourless 1px link hairlines fall back to currentColor. */
  .homepage-nav-mobile-menu .mobile-menu-section,
  .homepage-nav-mobile-menu .mobile-menu-section > a {
    border-color: #2d333b !important;
  }

  /* www marketing nav glyphs: hardcoded brown strokes, and the same brown as
     ink on trigger labels and dropdown links. */
  .homepage-nav .homepage-nav-search-bar svg,
  .homepage-nav .homepage-nav-back-link svg,
  .homepage-nav .homepage-nav-for-writers > svg path,
  .homepage-nav .homepage-nav-were-hiring > svg path {
    stroke: #8b949e !important;
  }
  .homepage-nav .homepage-nav-for-writers > span,
  .homepage-nav .homepage-nav-were-hiring > span,
  .homepage-nav .dropdown-menu a {
    color: #e6edf3 !important;
  }

  /* Marketing / corporate pages: `#substack-home`, outside the Pencraft app
     and its tokens. Brand bands deliberately NOT matched: orange `hero-`,
     `testimonialBand-`, `finalCta-`, yellow `cardTint-`. The vs-comparison hero
     needs its own `aria-labelledby`: its `hero-<hash>` shape is shared with the
     orange /about hero. */
  #substack-home .cohort-page,
  #substack-home .cohort-page .cohort-link,
  #substack-home .cohort-page .cohort-example a,
  #substack-home .cohort-page .case-study a,
  #substack-home .going-paid-guide-page,
  #substack-home .grow-page .event,
  #substack-home .jobs-page,
  #substack-home [class*="jobs-page-team"],
  #substack-home .resources-page,
  #substack-home .new-landing-page .publication,
  #substack-home .new-landing-page .publication-explanation-box .title,
  #substack-home .new-landing-page .publication-explanation-box .title > span,
  #substack-home .calculator,
  #substack-home .calculator .calculator-box .calculator-box-title,
  #substack-home .borderless-calculator-title,
  #substack-home [class*="customHeaderText"],
  #substack-home [class*="boldedCell"],
  #substack-home [class*="heroText1"],
  #substack-home [class*="partnerCardTitle"],
  #substack-home h3[class^="title-"],
  #substack-home .button.secondary {
    color: #e6edf3 !important;
  }
  /* Pills keep the site's white fill: `bg-white` also wraps publication logo
     chips, which must stay white. Only the LABEL is restated. The nav "Sign in"
     pill's label is a button, not a `color-` utility. */
  #substack-home [class*="bg-white"] [class*="color-primary"] {
    color: #1c2128 !important;
  }

  /* Guide/resource list glyphs ship a hardcoded black stroke. */
  #substack-home .resource-icon {
    stroke: #8b949e !important;
  }
  /* `tr` is safe unqualified — `#substack-home` never appears on a Pencraft
     app page. */
  #substack-home .featured-resource,
  #substack-home .resource,
  #substack-home .floating-navigator,
  #substack-home .button.big-button.secondary,
  #substack-home .cohort-hero,
  #substack-home .cohort-big-benefits,
  #substack-home .cohort-examples,
  #substack-home .cohort-substack-benefits,
  #substack-home .blogger-hero,
  #substack-home .case-study-section,
  #substack-home section.cookie,
  #substack-home [class*="containerBorderBottom"],
  #substack-home [class*="containerBorderTop"],
  #substack-home [class*="faqItem"],
  #substack-home tr,
  #substack-home hr {
    border-color: #2d333b !important;
  }
  #substack-home .featured-byline {
    color: #8b949e !important;
  }
  /* The site's hover wash is the cream #fafafa, under the light ink above. */
  #substack-home .resource:hover,
  #substack-home .featured-resource:hover {
    background-color: #262c33 !important;
  }

  /* Anchored to the route's `page-` wrapper: these stems are not unique to the
     routes (`heroSubtitle-` is white-on-orange on /about). The loose
     `[class*="page-"]` is safe as an ANCESTOR — it otherwise matches only
     `homepage-nav*`, where none of these stems live. Trailing `-` keeps
     `categoryTab-` off `categoryTabActive-`, whose selected state is correct.
     `statLabel` ships in both capitalisations. */
  #substack-home [class*="page-"] [class*="heroSubtitle-"],
  #substack-home [class*="page-"] [class*="heroDescription-"],
  #substack-home [class*="page-"] [class*="sectionDescription-"],
  #substack-home [class*="page-"] [class*="bulletText-"],
  #substack-home [class*="page-"] [class*="statLabel-"],
  #substack-home [class*="page-"] [class*="StatLabel-"],
  #substack-home [class*="page-"] [class*="testimonialCardPub-"],
  #substack-home [class*="page-"] [class*="testimonialCardQuote-"],
  #substack-home [class*="page-"] [class*="bottomCtaDescription-"],
  #substack-home [class*="page-"] [class*="categoryTab-"],
  #substack-home [class*="page-"] [class*="campaignPromptDescription-"],
  #substack-home [class*="page-"] [class*="stepIndicator-"],
  #substack-home [class*="page-"] [class*="legalText-"],
  #substack-home [class*="page-"] [class*="legalLink-"],
  #substack-home [class*="page-"] [class*="waysToPartnerSubtitle-"],
  #substack-home [class*="page-"] [class*="waysToPartnerCaption-"],
  #substack-home [class*="page-"] [class*="partnerCardDescription-"],
  #substack-home [class*="page-"] [class*="valuePropCopy-"] p,
  #substack-home [class*="page-"] [class*="becomeSponsorSubtitle-"],
  #substack-home [class*="page-"] [class*="becomeSponsorSectionLabel-"],
  #substack-home [class*="page-"] [class*="becomeSponsorLegal-"],
  #substack-home .calculator-fineprint,
  #substack-home .borderless-calculator-fineprint,
  #substack-home .cohort-page .form-info {
    color: #8b949e !important;
  }

  /* The photo panel is already dark and stays. `page-` is matched at a word
     boundary — a bare `[class*="page-"]` would swallow `homepage-nav*`. */
  #substack-home [class^="page-"],
  #substack-home [class*=" page-"],
  #substack-home [class*="page-"] [class*="rightPanel-"] {
    background-color: #14181d !important;
  }
  /* Ink, hairline and hover wash were all drawn for the cream. */
  #substack-home [class*="page-"] [class*="secondaryButton-"] {
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  #substack-home [class*="page-"] [class*="secondaryButton-"]:hover {
    background-color: #262c33 !important;
  }

  /* The CTA paints its copy with the light-scheme SURFACE primitive to read
     white on the green band; we remap that primitive, so restate the white. */
  #substack-home [class*="finalCtaBody"] {
    color: #ffffff !important;
  }

  /* Outline is the same brown as the ink. */
  #substack-home .cohort-page .event-item .hosted-pill {
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* Full-bleed light section fills; tinted/who/gradient members also paint a
     peach wash as background-IMAGE, which background-color alone does not clear.
     `^=` members need prefix matching — `[class*="jobsHero"]` would swallow
     jobsHeroButton and jobsHeroImage inside the band. `comparisonsContainer` is
     translucent rgba(200, 200, 200, 0.2): composites LIGHTER than this canvas and
     than the cards on it. */
  #substack-home [class*="statsStrip"],
  #substack-home [class^="jobsHero-"],
  #substack-home [class^="buildSection-"],
  #substack-home [class^="marqueeBackground-"],
  #substack-home [class*="sectionTinted"],
  #substack-home [class*="sectionWhite"],
  #substack-home [class*="sectionWho"],
  #substack-home [class*="sectionCream"],
  #substack-home [class*="toolsSection"],
  #substack-home [class*="topGradientRegion"],
  #substack-home [class*="bottomGradientRegion"],
  #substack-home [class*="testimonialImagePane"],
  #substack-home [class*="heroLogoBackdrop"],
  #substack-home section[class*="valueProp"],
  #substack-home section[class*="waysToPartner"],
  #substack-home section[class*="becomeSponsor"],
  #substack-home section[class*="testimonial-"],
  #substack-home [class*="jobPerks"],
  #substack-home [class*="comparisonsContainer"],
  #substack-home section[aria-labelledby="hero-heading"] {
    background-color: #14181d !important;
    background-image: none !important;
  }
  /* Black-linework PNGs drawn for the cream bands; hue-rotate keeps colour
     inside the mark. Scoped to the logo strip and quote band — the hero holds
     photographs. */
  #substack-home [class*="logoStripImage"],
  #substack-home section[class*="testimonial-"] img {
    filter: invert(1) hue-rotate(180deg) !important;
  }

  /* `heroCard` at a word boundary: `heroCardGrid-`/`heroCardBody-` are
     natively transparent over the green brand band, so a substring match darkens
     the gutters. */
  #substack-home [class*="benefitCard"],
  #substack-home [class^="heroCard-"],
  #substack-home [class*=" heroCard-"],
  #substack-home [class*="heroCreatorCard"],
  #substack-home [class*="compareTableScrollInn"],
  #substack-home [class*="startOptionCard"],
  #substack-home [class*="press-grid"] > div,
  #substack-home .borderless-calculator,
  #substack-home .calculator .calculator-box,
  #substack-home .going-paid-guide-page .banner,
  #substack-home .resources-page .banner {
    background-color: #1c2128 !important;
    background-image: none !important;
  }

  /* www marketing footer */
  .www-footer {
    background-color: #14181d !important;
  }
  .www-footer h1,
  .www-footer h2,
  .www-footer h3,
  .www-footer h4 {
    color: #e6edf3 !important;
  }
  /* Column links ship a hardcoded #808080 (4.4:1 here). */
  .www-footer .footer-info-col a {
    color: #8b949e !important;
  }
  /* WHITE lockups on a white anchor; inverting yields the vendors' own BLACK
     lockup rather than an off-brand recolour, and hue-rotate keeps the Play
     triangle's colours. */
  .www-footer .app-badge {
    background-color: #14181d !important;
  }
  .www-footer .app-badge img {
    filter: invert(1) hue-rotate(180deg) !important;
  }

  /* Discover / not-found landing hero */
  .new-landing-page .display-type {
    color: #e6edf3 !important;
  }

  /* Text selection */
  ::selection {
    background-color: rgba(95, 176, 230, 0.3);
  }
}

@-moz-document domain("support.substack.com") {
/* Consumed only as backgrounds and borders. --gray-light stays: dual-role,
     and still 4.6:1 as ink. */
  :root {
    --gray-lighter: #262c33 !important;
    --gray-lightest: #1c2128 !important;
    --meta-text-color: #8b949e !important;
    --input-border-color: #2d333b !important;
    --input-focus-border-color: #4a515a !important;
  }

  /* `body`'s ink is what everything inherits; the rest of the list is each
     component where the theme restates it. */
  body,
  .lt-skip-navigation,
  .lt-topbar__link,
  .lt-topbar__controls,
  .lt-btn--topbar,
  .lt-btn--print,
  .breadcrumbs > li:last-child a,
  .lt-contact-box,
  .lt-contact-box__title,
  .lt-custom-block__title,
  .lt-custom-block__link,
  .lt-section-link,
  .lt-article-box,
  .lt-search-filter__link,
  .lt-profile-stats__value,
  .lt-profile-nav__item a,
  .lt-promoted-articles-accordion-item__title,
  .lt-my-activities-menu--main .lt-my-activities-menu-item.is-active,
  .lt-vote__control--active,
  .lt-post-status--not-planned,
  .lt-status-label--not-planned,
  .recent-articles ul > li a,
  .related-articles ul > li a,
  .tabs-link,
  .upload-dropzone span,
  .lt-footer,
  .lt-footer__social-link,
  .callout {
    color: #e6edf3 !important;
  }

  /* #0c9 is the site's own brighter green. No !important on purpose: the
     white-on-brand links then keep winning on specificity, as they do
     natively. */
  a {
    color: #00cc99;
  }
  /* The theme's bare `a:hover` is #00231d, invisible here; same specificity,
     no !important, so the more specific brand-link hovers still win. */
  a:hover,
  a:focus {
    color: #66e0bd;
  }
  /* Green as INK (glyph + outline), not fill. A `button`, so the `a` rule
     above misses it; its native hover goes DARKER, so here hover moves UP the
     ramp. */
  .lt-scroll-to-top {
    color: #00cc99 !important;
    border-color: #00cc99 !important;
  }
  .lt-scroll-to-top:hover,
  .lt-scroll-to-top:focus {
    color: #66e0bd !important;
    border-color: #66e0bd !important;
  }

  /* The current crumb keeps the bright ink above — `:last-child` outranks
     this. The `›` separators are a pseudo with the same grey. */
  .breadcrumbs > li a,
  .breadcrumbs > li + li::before {
    color: #8b949e !important;
  }

  .lt-footer__copyright a,
  .lt-topbar__link:hover,
  .lt-topbar__link:focus,
  .lt-topbar__link:active,
  .lt-btn--topbar:hover,
  .lt-btn--topbar:focus,
  .lt-btn--topbar:active {
    color: #00cc99 !important;
  }

  /* The ink list above is `!important`, so on ANCHOR members it outranks the
     theme's own `a:hover`; hover is restated here, moving UP the ramp where the
     theme's goes darker. `.lt-contact-box__title` is in that list and inherits its
     anchor's hover natively, hence the descendant arm. `.lt-custom-block__link` is
     deliberately absent: every text node inside carries its own colour. */
  .lt-contact-box:hover,
  .lt-contact-box:focus,
  .lt-contact-box:hover .lt-contact-box__title,
  .lt-contact-box:focus .lt-contact-box__title,
  .lt-article-box:hover,
  .lt-article-box:focus,
  .lt-section-link:hover,
  .lt-section-link:focus {
    color: #00cc99 !important;
  }

  /* The --gray-* remap above already carries the breadcrumb bar, article box,
     vote footer and blockquotes. */
  .lt-topbar,
  .lt-footer {
    background-color: #14181d !important;
  }
  .lt-skip-navigation,
  .lt-topbar__controls,
  .lt-dropdown-menu,
  .table .table {
    background-color: #1c2128 !important;
  }
  .lt-dropdown-menu [role="menuitem"]:hover,
  .lt-dropdown-menu [role="menuitem"]:focus,
  .accordion--default .accordion__item-title--active {
    background-color: #262c33 !important;
    color: #e6edf3 !important;
  }

  /* The theme repaints the field solid white on focus, hiding the query under
     the light ink above. */
  .lt-search-box #query:focus {
    background-color: #1c2128 !important;
    border-color: #4a515a !important;
  }

  /* Meaning lives in the left/edge border colour, which stays; only the pale
     fill moves. */
  .callout--success,
  .callout--info,
  .callout--warning,
  .callout--danger,
  .callout--primary,
  .notification-error,
  .notification-notice,
  .notification-alert,
  .notification-inline {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
  }

  /* Background-only rule, so the light ink above would land on pale yellow. */
  .lt-search-result__text em {
    color: #14181d !important;
  }
}
